1	// Meeting-room booking server: JSON API + static page, data kept in one JSON file.
2	// Node.js built-ins only. Startup order: PORT check -> data file read -> listen.
3	import http from 'node:http';
4	import { readFileSync } from 'node:fs';
5	import { readFile, rename, unlink, writeFile } from 'node:fs/promises';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
10	const MAX_BODY_BYTES = 10000;
11	const MAX_TITLE_LENGTH = 80;
12	const DEFAULT_PORT = 3000;
13	const MAX_PORT = 65535;
14	const HOST = '127.0.0.1';
15	const JSON_TYPE = 'application/json; charset=utf-8';
16	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
17	const PAGE_FILES = Object.freeze({
18	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
19	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
20	});
21	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
22	const BOOKINGS_PREFIX = '/api/bookings/';
23	const DATE_ERROR = 'date must be a valid YYYY-MM-DD date';
24	
25	class HttpError extends Error {
26	  constructor(status, message) {
27	    super(message);
28	    this.status = status;
29	  }
30	}
31	
32	// ---------- validation helpers ----------
33	
34	function isPlainObject(value) {
35	  return typeof value === 'object' && value !== null && !Array.isArray(value);
36	}
37	
38	function isValidDate(value) {
39	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
40	  const year = Number(value.slice(0, 4));
41	  const month = Number(value.slice(5, 7));
42	  const day = Number(value.slice(8, 10));
43	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
44	  const febDays = year % 4 === 0 ? 29 : 28;
45	  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
46	  return day <= monthDays[month - 1];
47	}
48	
49	function isValidTime(value) {
50	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
51	  return Number(value.slice(0, 2)) <= 23 && Number(value.slice(3, 5)) <= 59;
52	}
53	
54	function ownField(object, key) {
55	  return Object.hasOwn(object, key) ? object[key] : undefined;
56	}
57	
58	function overlaps(a, b) {
59	  return a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
60	}
61	
62	// Rules 4-9: returns a new booking draft (without id) or throws HttpError 400.
63	function validateBookingFields(body) {
64	  const room = ownField(body, 'room');
65	  if (typeof room !== 'string' || !ROOMS.includes(room)) {
66	    throw new HttpError(400, 'room must be one of Aurora, Borealis, Cosmos');
67	  }
68	  const rawTitle = ownField(body, 'title');
69	  const title = typeof rawTitle === 'string' ? rawTitle.trim() : '';
70	  if (title.length < 1 || title.length > MAX_TITLE_LENGTH) {
71	    throw new HttpError(400, 'title must be 1 to 80 characters');
72	  }
73	  const date = ownField(body, 'date');
74	  if (!isValidDate(date)) throw new HttpError(400, DATE_ERROR);
75	  const start = ownField(body, 'start');
76	  if (!isValidTime(start)) throw new HttpError(400, 'start must be HH:MM');
77	  const end = ownField(body, 'end');
78	  if (!isValidTime(end)) throw new HttpError(400, 'end must be HH:MM');
79	  if (end <= start) throw new HttpError(400, 'end must be after start');
80	  return { room, title, date, start, end };
81	}
82	
83	function compareBookings(a, b) {
84	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
85	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
86	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
87	}
88	
89	// ---------- data file ----------
90	
91	function isValidStoredBooking(entry, nextId) {
92	  if (!isPlainObject(entry)) return false;
93	  const keys = Object.keys(entry);
94	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
95	  const { id, room, title, date, start, end } = entry;
96	  return Number.isSafeInteger(id) && id >= 1 && id < nextId
97	    && typeof room === 'string' && ROOMS.includes(room)
98	    && typeof title === 'string' && title === title.trim()
99	    && title.length >= 1 && title.length <= MAX_TITLE_LENGTH
100	    && isValidDate(date) && isValidTime(start) && isValidTime(end) && start < end;
101	}
102	
103	// Returns a fresh state, or null when the data is not in this server's layout.
104	function parseState(text) {
105	  let data;
106	  try {
107	    data = JSON.parse(text);
108	  } catch {
109	    return null;
110	  }
111	  if (!isPlainObject(data)) return null;
112	  const keys = Object.keys(data);
113	  if (keys.length !== 2 || !keys.includes('nextId') || !keys.includes('bookings')) return null;
114	  const { nextId, bookings } = data;
115	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return null;
116	  if (!bookings.every((b) => isValidStoredBooking(b, nextId))) return null;
117	  if (new Set(bookings.map((b) => b.id)).size !== bookings.length) return null;
118	  const clash = bookings.some((a, i) => bookings.some((b, j) => i < j && overlaps(a, b)));
119	  if (clash) return null;
120	  return Object.freeze({ nextId, bookings: Object.freeze(bookings.map((b) => Object.freeze({ ...b }))) });
121	}
122	
123	function loadState(filePath) {
124	  let buffer;
125	  try {
126	    buffer = readFileSync(filePath);
127	  } catch (error) {
128	    if (error && error.code === 'ENOENT') return Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
129	    return null;
130	  }
131	  return parseState(buffer.toString('utf8'));
132	}
133	
134	// Writes a sibling temp file and renames it over the data file, so an
135	// interrupted save never leaves a truncated file behind.
136	async function saveState(filePath, state) {
137	  const payload = { nextId: state.nextId, bookings: state.bookings };
138	  const tempPath = `${filePath}.${process.pid}.tmp`;
139	  try {
140	    await writeFile(tempPath, `${JSON.stringify(payload, null, 2)}\n`, 'utf8');
141	    await rename(tempPath, filePath);
142	  } catch (error) {
143	    await unlink(tempPath).catch(() => undefined); // best-effort cleanup; the save error below is what matters
144	    throw error;
145	  }
146	}
147	
148	// ---------- request / reply helpers ----------
149	
150	// Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes but counts all of them.
151	function readBody(req) {
152	  return new Promise((resolve, reject) => {
153	    const chunks = [];
154	    let kept = 0;
155	    let total = 0;
156	    req.on('data', (chunk) => {
157	      total += chunk.length;
158	      if (kept <= MAX_BODY_BYTES) {
159	        chunks.push(chunk);
160	        kept += chunk.length;
161	      }
162	    });
163	    req.on('end', () => resolve({ buffer: Buffer.concat(chunks), size: total }));
164	    req.on('error', reject);
165	  });
166	}
167	
168	function sendJson(res, status, value) {
169	  const body = Buffer.from(JSON.stringify(value), 'utf8');
170	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': body.length });
171	  res.end(body);
172	}
173	
174	function sendError(res, status, message) {
175	  sendJson(res, status, { error: message });
176	}
177	
178	function mediaTypeIsJson(header) {
179	  if (typeof header !== 'string') return false;
180	  const mediaType = header.split(';', 1)[0].replace(/^[ \t]+|[ \t]+$/g, '');
181	  // Fold ASCII letters only, on purpose: "letter case ignored" means A-Z here.
182	  return mediaType.replace(/[A-Z]/g, (c) => c.toLowerCase()) === 'application/json';
183	}
184	
185	function parseJsonObject(buffer) {
186	  try {
187	    const value = JSON.parse(buffer.toString('utf8'));
188	    return isPlainObject(value) ? value : null;
189	  } catch {
190	    return null;
191	  }
192	}
193	
194	// ---------- app ----------
195	
196	function createApp(dataPath, initialState) {
197	  let state = initialState;
198	  let lock = Promise.resolve();
199	
200	  // Runs mutations one at a time so concurrent requests behave as if sequential.
201	  function serialized(task) {
202	    const run = lock.then(task);
203	    lock = run.then(() => undefined, () => undefined);
204	    return run;
205	  }
206	
207	  async function commit(nextState) {
208	    await saveState(dataPath, nextState);
209	    state = nextState;
210	  }
211	
212	  function listBookings(res, query) {
213	    const params = new URLSearchParams(query);
214	    let bookings = state.bookings;
215	    if (params.has('date')) {
216	      const date = params.get('date');
217	      if (!isValidDate(date)) throw new HttpError(400, DATE_ERROR);
218	      bookings = bookings.filter((b) => b.date === date);
219	    }
220	    sendJson(res, 200, { bookings: [...bookings].sort(compareBookings) });
221	  }
222	
223	  function createBooking(req, res, body) {
224	    if (!mediaTypeIsJson(req.headers['content-type'])) {
225	      throw new HttpError(415, 'content type must be application/json');
226	    }
227	    if (body.size > MAX_BODY_BYTES) throw new HttpError(413, 'body too large');
228	    const parsed = parseJsonObject(body.buffer);
229	    if (parsed === null) throw new HttpError(400, 'body must be a JSON object');
230	    const draft = validateBookingFields(parsed);
231	    return serialized(async () => {
232	      const clashes = state.bookings.filter((b) => overlaps(b, draft)).sort(compareBookings);
233	      if (clashes.length > 0) {
234	        throw new HttpError(409, `room is already booked from ${clashes[0].start} to ${clashes[0].end}`);
235	      }
236	      const booking = Object.freeze({ id: state.nextId, ...draft });
237	      await commit(Object.freeze({
238	        nextId: state.nextId + 1,
239	        bookings: Object.freeze([...state.bookings, booking]),
240	      }));
241	      sendJson(res, 201, booking);
242	    });
243	  }
244	
245	  function deleteBooking(res, idText) {
246	    return serialized(async () => {
247	      const valid = /^[1-9][0-9]*$/.test(idText);
248	      const target = valid ? state.bookings.find((b) => String(b.id) === idText) : undefined;
249	      if (!target) throw new HttpError(404, 'booking not found');
250	      await commit(Object.freeze({
251	        nextId: state.nextId,
252	        bookings: Object.freeze(state.bookings.filter((b) => b !== target)),
253	      }));
254	      res.writeHead(204);
255	      res.end();
256	    });
257	  }
258	
259	  async function servePage(res, page) {
260	    const content = await readFile(path.join(PUBLIC_DIR, page.file));
261	    res.writeHead(200, { 'Content-Type': page.type, 'Content-Length': content.length });
262	    res.end(content);
263	  }
264	
265	  async function route(req, res, body) {
266	    const target = req.url;
267	    const cut = target.indexOf('?');
268	    const pathname = cut === -1 ? target : target.slice(0, cut);
269	    const query = cut === -1 ? '' : target.slice(cut + 1);
270	    const { method } = req;
271	
272	    if (pathname === '/api/rooms') {
273	      if (method !== 'GET') throw new HttpError(405, 'method not allowed');
274	      return sendJson(res, 200, { rooms: [...ROOMS] });
275	    }
276	    if (pathname === '/api/bookings') {
277	      if (method === 'GET') return listBookings(res, query);
278	      if (method === 'POST') return createBooking(req, res, body);
279	      throw new HttpError(405, 'method not allowed');
280	    }
281	    if (pathname.startsWith(BOOKINGS_PREFIX)) {
282	      const idText = pathname.slice(BOOKINGS_PREFIX.length);
283	      if (idText === '' || idText.includes('/')) throw new HttpError(404, 'not found');
284	      if (method !== 'DELETE') throw new HttpError(405, 'method not allowed');
285	      return deleteBooking(res, idText);
286	    }
287	    if (Object.hasOwn(PAGE_FILES, pathname)) {
288	      if (method !== 'GET') throw new HttpError(405, 'method not allowed');
289	      return servePage(res, PAGE_FILES[pathname]);
290	    }
291	    throw new HttpError(404, 'not found');
292	  }
293	
294	  return async function handle(req, res) {
295	    let body;
296	    try {
297	      body = await readBody(req);
298	    } catch {
299	      // The client went away mid-body; there is nobody left to reply to.
300	      req.destroy();
301	      return;
302	    }
303	    try {
304	      await route(req, res, body);
305	    } catch (error) {
306	      if (res.headersSent) {
307	        res.destroy();
308	        return;
309	      }
310	      if (error instanceof HttpError) sendError(res, error.status, error.message);
311	      else sendError(res, 500, 'internal error');
312	    }
313	  };
314	}
315	
316	// ---------- startup ----------
317	
318	function fail(line) {
319	  process.stderr.write(`${line}\n`);
320	  process.exit(1);
321	}
322	
323	function parsePort(raw) {
324	  if (raw === undefined || raw === '') return DEFAULT_PORT;
325	  if (!/^[0-9]+$/.test(raw)) return null;
326	  const port = Number(raw);
327	  return port <= MAX_PORT ? port : null;
328	}
329	
330	function main() {
331	  const port = parsePort(process.env.PORT);
332	  if (port === null) fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
333	
334	  const dataName = process.env.DATA_FILE ? process.env.DATA_FILE : 'bookings.json';
335	  const dataPath = path.resolve(process.cwd(), dataName);
336	  const state = loadState(dataPath);
337	  if (state === null) fail(`cannot read data file ${dataName}`);
338	
339	  const server = http.createServer(createApp(dataPath, state));
340	  server.on('error', (error) => fail(`cannot listen on port ${port}: ${error.code || 'error'}`));
341	  server.listen(port, HOST, () => {
342	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
343	  });
344	}
345	
346	main();
